from __future__ import annotations

import json
import os
import sys
import threading
from pathlib import Path
from types import SimpleNamespace

from PIL import Image


_LOCK = threading.Lock()


def predict(input_path: str, engine_path: str, output_dir: str) -> dict:
    engine = Path(engine_path).resolve()
    output = Path(output_dir).resolve()
    output.mkdir(parents=True, exist_ok=True)
    sys.path.insert(0, str(engine))

    with _LOCK:
        previous = Path.cwd()
        try:
            os.chdir(engine)
            from kl_process import seg_class_function

            args = SimpleNamespace(
                img_name=str(Path(input_path).resolve()), narrow_type="lower_upper_mean",
                box_size=672, save_folder=str(output), shape=(672, 672), mode=2,
            )
            raw, segmented, medial, lateral, grades = seg_class_function(args)
        finally:
            os.chdir(previous)

    stem = Path(input_path).stem
    original_path = output / f"{stem}_original_radiograph.png"
    Image.fromarray(raw.astype("uint8"), mode="L").convert("RGB").save(original_path)
    knee_overlay_files = []
    for index, side in enumerate(("right", "left")):
        path = output / f"{stem}_{side}_knee_segmentation.png"
        Image.fromarray(segmented[index].astype("uint8"), mode="RGB").save(path)
        knee_overlay_files.append(str(path))
    knees = []
    for index, side in enumerate(("right", "left")):
        grade = int(grades[index])
        knees.append({
            "side": side, "kl_grade": grade, "oa_present": grade >= 2,
            "medial_jsn_grade": int(medial[index]),
            "lateral_jsn_grade": int(lateral[index]),
        })
    result = {
        "model": "Duke knee OA KL and JSN pipeline",
        "knees": knees,
        "original_file": str(original_path),
        "knee_overlay_files": knee_overlay_files,
    }
    (output / f"{stem}_result.json").write_text(
        json.dumps(result, indent=2) + "\n"
    )
    return result


